import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, texture, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ─────────────────────────────────────────────────────────────────
  // SETUP: Extract configuration
  // ─────────────────────────────────────────────────────────────────
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/orb-decor.png';
  const scenePos = config.scenePosition || [-3.2, -0.3, 0];
  const sceneRot = config.sceneRotation || [0, 0, 0];
  const sceneScale = config.sceneScale || [1, 1, 1];

  // Aspect ratio from atlas region (512 x 320 = 1.6:1)
  const atlasW = 512;
  const atlasH = 320;
  const aspectRatio = atlasW / atlasH; // ~1.6

  // ─────────────────────────────────────────────────────────────────
  // GEOMETRY: Plane matching atlas aspect
  // ─────────────────────────────────────────────────────────────────
  const planeHeight = 1.2; // scene units
  const planeWidth = planeHeight * aspectRatio; // ~1.92

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight, 1, 1);

  // ─────────────────────────────────────────────────────────────────
  // MATERIAL: MeshBasicNodeMaterial with TSL shader
  // ─────────────────────────────────────────────────────────────────
  let texMap = null;
  const texUniform = uniform(null);

  // Load texture asynchronously (non-blocking return)
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    texMap = tex;
    texUniform.value = tex;
  });

  // TSL shader: base texture + subtle grain overlay
  const uvNode = uv();

  // Simple grain pattern (via sin-based noise)
  const grain = mix(
    vec4(1.0),
    vec4(0.97),
    texture(texUniform).mul(0.05)
  );

  const material = new MeshBasicNodeMaterial({
    colorNode: texture(texUniform).mul(grain),
    side: THREE.FrontSide,
    transparent: true,
  });

  // ─────────────────────────────────────────────────────────────────
  // MESH: Position, rotation, scale from spec
  // ─────────────────────────────────────────────────────────────────
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.fromArray(scenePos);
  mesh.rotation.order = 'XYZ';
  mesh.rotation.fromArray(sceneRot);
  mesh.scale.fromArray(sceneScale);

  // ─────────────────────────────────────────────────────────────────
  // CONTAINER: Root object
  // ─────────────────────────────────────────────────────────────────
  const root = new THREE.Group();
  root.add(mesh);

  // ─────────────────────────────────────────────────────────────────
  // CLEANUP: Dispose resources
  // ─────────────────────────────────────────────────────────────────
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texMap) {
      texMap.dispose();
    }
  };

  // ─────────────────────────────────────────────────────────────────
  // HANDLERS: No interactivity (static composition per spec)
  // ─────────────────────────────────────────────────────────────────
  root.userData.handlers = {};

  return root;
}
